import numpy as np
from itertools import combinations

def is_complete(adj_matrix, vertices_subset):
    """Checks if the subgraph induced by vertices_subset is complete."""
    n = adj_matrix.shape[0]
    induced_subgraph = np.zeros((len(vertices_subset), len(vertices_subset)), dtype=int)

    # Mapping from original index to subset index
    v_map = {v: i for i, v in enumerate(vertices_subset)}

    for i in range(len(vertices_subset)):
        u = vertices_subset[i]
        for j in range(i + 1, len(vertices_subset)):
            v = vertices_subset[j]
            # Check connectivity in the original graph
            if adj_matrix[u, v] == 1:
                induced_subgraph[i, j] = 1
                induced_subgraph[j, i] = 1

    # Check if all pairs are connected (i.e., diagonal is 0, and all off-diagonals are 1)
    if induced_subgraph.shape[0] < 2:
        return True # Trivial case

    # For a complete graph K_k, the number of edges is k*(k-1)/2.
    # The number of required edges is len(vertices_subset) * (len(vertices_subset) - 1) / 2
    expected_edges = len(vertices_subset) * (len(vertices_subset) - 1) // 2

    edge_count = 0
    for i in range(len(vertices_subset)):
        for j in range(i + 1, len(vertices_subset)):
            if adj_matrix[vertices_subset[i], vertices_subset[j]] == 1:
                edge_count += 1

    return edge_count == expected_edges


def count_tetrahedra(adj_matrix):
    """Counts the number of K4 subgraphs (tetrahedra) in the graph."""
    n = adj_matrix.shape[0]
    tetrahedra_count = 0
    # Iterate over all subsets of 4 vertices
    for subset in combinations(range(n), 4):
        if is_complete(adj_matrix, list(subset)):
            tetrahedra_count += 1
    return tetrahedra_count

def count_triangles(adj_matrix):
    """Counts the number of K3 subgraphs (triangles) in the graph using trace method."""
    A = adj_matrix.astype(float)
    A_cubed = np.linalg.matrix_power(A, 3)
    # Sum of diagonal entries is 6 * f(G)
    f_G = np.trace(A_cubed) / 6.0
    # Since we are dealing with integers, we round it
    return int(round(f_G))

def calculate_ratio(f_G, g_G):
